import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_ENDPOINTS } from '../Service/apiConfig';

const MediaLibraryModal = ({ onSelect, onClose }) => {
    const [images, setImages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filteredImages, setFilteredImages] = useState([]);

    useEffect(() => {
        fetch(`${API_ENDPOINTS.images}`)
            .then(response => response.json())
            .then(data => {
                if (data.status === 200 && data.data) {
                    setImages(data.data);
                }
            })
            .catch(error => console.error("Error fetching images:", error))
            .finally(() => setLoading(false));
    }, []);

    const handleImageUpload = async (event) => {
        const files = event.target.files;
        const formData = new FormData();

        for (let file of files) {
            formData.append("image[]", file);
        }

        try {
            const response = await axios.post(API_ENDPOINTS.uploadImage, formData, {
                headers: {
                    "Content-Type": "multipart/form-data",
                },
            });

            if (response.data && response.data.data) {
                const updatedImages = await axios.get(API_ENDPOINTS.images);
                if (updatedImages.data && updatedImages.data.data) {
                    setImages(updatedImages.data.data);
                    // setFilteredImages(updatedImages.data.data); // Update filtered images
                }
            } else {
                console.error("Upload failed:", response.data);
            }
        } catch (error) {
            console.error("Error uploading images:", error);
        }
    };

    const handleSearch = (query) => {
        if (!query) {
            setFilteredImages(images);
        } else {
            const filtered = images.filter(image =>
                image.image.toLowerCase().includes(query.toLowerCase())
            );
            setFilteredImages(filtered);
        }
    };

    return (
        <div className="fixed inset-0 bg-black bg-opacity-90 flex justify-center items-center">
            <div className="m-auto bg-gray-50 p-6 rounded-lg shadow-lg w-[600px] max-h-[80vh] overflow-y-auto">
                <h2 className="text-lg font-semibold mb-0">Select an Image</h2>

                <div className="flex justify-start py-2 items-center gap-2">
                    <div className="relative max-w-sm">
                        <input className="w-60 px-4 h-9 rounded-md shadow-sm" type="search" placeholder="Search images"/>
                    </div>
                    <div className="mb-1">
                <label className="cursor-pointer bg-blue-600 text-white px-3 py-2 rounded-lg hover:bg-blue-700">
                    <i className="ti ti-photo-up text-xl text-white mr-2"></i>
                    Upload
                    <input
                        type="file"
                        accept="image/*"
                        multiple
                        className="hidden"
                        onChange={handleImageUpload}
                    />
                </label>
                {/* <span className='ml-2 text-gray-600'>{selectedImageName}</span> */}
            </div>
                </div>

                {loading ? (
                    <p className="text-center py-4">Loading images...</p>
                ) : (
                    <div className="grid grid-cols-4 gap-4">
                        {images.map((image) => (
                            <div key={image.imageId} className="relative border rounded-lg overflow-hidden cursor-pointer"
                                onClick={() => {
                                    onSelect(image.image);
                                    onClose();
                                }}>
                                <img src={`${image.image_url}`}
                                     alt={`Media ${image.name}`}
                                     className="w-full h-auto object-cover" />
                            </div>
                        ))}
                    </div>
                )}

                <button className="mt-4 px-4 py-2 bg-red-500 text-white rounded-lg" onClick={onClose}>
                    Close
                </button>
                <span className='mx-2'>123.jpg</span>
            </div>
        </div>
    );
};

export default MediaLibraryModal;
